-- Migration 030: Inhalte der Hauptquest (Chronik, Kapitel 1–3) und Aushänge des Dorfes. Erzeugt von quests/chronik.py.
insert into public.quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, def)
select e->>'id', e->>'titel', e->>'kurz', e->>'kurz', 'chronik', (e->>'kapitel')::int, e->'rollen', e->'def' from jsonb_array_elements($q$[{"id":"chronik_1","titel":"Ein Platz am Feuer","kurz":"Seit Meister Gundram gestorben ist, hat das Dorf keinen Dorfmeister. {V} hält es zusammen, so gut es geht – und sieht dich an.","kapitel":1,"rollen":{"V":"Vorsteher","A":"Wer Hilfe auf dem Feld braucht","B":"Streithahn am Zaun","C":"Nachbar am Zaun"},"def":{"start":"brunnen","szenen":{"brunnen":{"ort":"dorf","text":"Früher Morgen am Brunnen. {V} schöpft Wasser und stellt den Eimer ab, als du kommst. „Seit Meister Gundram im letzten Winter gestorben ist, hält dieses Dorf niemand richtig zusammen. Ich tue, was ich kann – aber ich bin Vorsteher aus Verlegenheit, nicht aus Berufung.“ Er mustert dich. „Du lebst hier, {held}. Aber hier leben und dazugehören sind zwei verschiedene Dinge.“","optionen":[{"text":"„Was braucht das Dorf gerade?“","weiter":"aufgaben"},{"text":"„Wer entscheidet jetzt, wenn ihr euch streitet?“","weiter":"aufgaben","ergebnis":"„Ich, notgedrungen. Bis die Versammlung einen neuen Dorfmeister wählt.“ Er zuckt die Schultern. „Aufgestellt wird nur, wen die Leute kennen und schätzen. Ansehen kann man nicht kaufen – man sammelt es, eine Hand voll Hilfe nach der anderen.“","folgen":{"flag":["wahl_erklaert"]}},{"text":"„Ich will eigentlich nur meine Ruhe.“","weiter":"aufgaben","ergebnis":"{V} lacht kurz. „Die wollen wir alle. Ruhe gibt es aber nur, wenn jemand die Unruhe wegräumt.“","folgen":{"flag":["ruhe"]}}]},"aufgaben":{"ort":"dorf","text":"„Zwei Dinge liegen heute an“, sagt {V}. „{A} kriegt das Korn allein nicht vom Feld, und es zieht Regen auf. Und {B} und {C} streiten seit drei Tagen um einen Zaun – bald fliegen da Steine.“","optionen":[{"text":"Zuerst aufs Feld zu {A}","weiter":"feld"},{"text":"Zuerst zum Zaunstreit","weiter":"zaun"}]},"feld":{"ort":"feld","text":"Die Garben liegen noch auf dem Acker, der Himmel im Westen wird grau. {A} wischt sich den Schweiß von der Stirn. „Allein schaffe ich das nie, bevor es gießt.“","optionen":[{"text":"Mit anpacken","tag":"[Anpacken]","probe":{"id":"anpacken","dc":11},"erfolg":{"text":"Garbe um Garbe schleppt ihr in die Scheune. Als die ersten Tropfen fallen, liegt die letzte im Trockenen.","folgen":{"flag":["feld_besucht","feld_gut"],"sym":{"A":4},"merkt":{"A":"{held} hat mir geholfen, das Korn vor dem Regen einzubringen."}},"weiter":"zwischen"},"misserfolg":{"text":"Ihr schuftet, aber der Regen ist schneller. Ein Teil der Garben wird nass – immerhin nicht alle.","folgen":{"flag":["feld_besucht","feld_halb"],"sym":{"A":2}},"weiter":"zwischen"}},{"text":"Die Nachbarskinder als Helfer holen","tag":"[Überreden]","probe":{"id":"ueberreden","dc":10},"erfolg":{"text":"Mit dem Versprechen von Honigbrot rennen fünf Kinder los. Lachend schleppen sie Garben, und der Regen findet nur noch leere Stoppeln.","folgen":{"flag":["feld_besucht","feld_gut","kinder"],"sym":{"A":3},"merkt":{"A":"{held} hat das halbe Dorf zum Ernten zusammengetrommelt."}},"weiter":"zwischen"},"misserfolg":{"text":"Die Kinder kommen – und verschwinden nach der ersten Garbe wieder. Du und {A} schafft den Rest gerade so.","folgen":{"flag":["feld_besucht","feld_halb"],"sym":{"A":2}},"weiter":"zwischen"}}]},"zaun":{"ort":"dorf","text":"{B} und {C} stehen sich am Zaun gegenüber, beide mit roten Köpfen. „Der Zaun steht seit meinem Großvater hier!“, ruft {B}. „Und seit deinem Großvater wandert er jedes Jahr eine Elle in meinen Garten“, gibt {C} zurück. Ein paar Nachbarn schauen schon zu.","optionen":[{"text":"Genau hinsehen, wer hier flunkert","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":12},"erfolg":{"text":"Frisch aufgeworfene Erde an den Pfosten, und {B} weicht deinem Blick aus. Der Zaun wurde versetzt – vor Kurzem. Du sagst es ruhig, ohne Triumph. {B} schluckt und nickt.","folgen":{"flag":["zaun_besucht","zaun_wahrheit"],"sym":{"C":4,"B":-1},"merkt":{"C":"{held} hat im Zaunstreit die Wahrheit herausgefunden."}},"weiter":"zwischen"},"misserfolg":{"text":"Du findest nichts Eindeutiges. Die beiden streiten weiter, nur etwas leiser.","folgen":{"flag":["zaun_besucht","zaun_offen"]},"weiter":"zwischen"}},{"text":"Einen neuen Zaun genau in der Mitte vorschlagen – gemeinsam gebaut","tag":"[Überreden]","probe":{"id":"ueberreden","dc":11},"erfolg":{"text":"Lange Stille. Dann lacht {C} auf. „Und wer bezahlt die Pfosten?“ – „Beide“, sagst du. Am Nachmittag graben sie Seite an Seite.","folgen":{"flag":["zaun_besucht","zaun_kompromiss"],"sym":{"B":3,"C":3},"merkt":{"B":"{held} hat den Zaunstreit mit {C} gütlich beigelegt.","C":"{held} hat den Zaunstreit mit {B} gütlich beigelegt."}},"weiter":"zwischen"},"misserfolg":{"text":"„In der Mitte? Dann verliere ich ja eine halbe Elle!“ Beide sind sich plötzlich einig – gegen dich. Immerhin streiten sie nicht mehr miteinander.","folgen":{"flag":["zaun_besucht","zaun_offen"],"sym":{"B":-1,"C":-1}},"weiter":"zwischen"}},{"text":"{B} recht geben","weiter":"zwischen","ergebnis":"{B} grinst. {C} spuckt aus und geht ins Haus. Das letzte Wort ist hier noch nicht gesprochen.","folgen":{"flag":["zaun_besucht","zaun_partei"],"sym":{"B":4,"C":-5}}},{"text":"{C} recht geben","weiter":"zwischen","ergebnis":"{C} nickt dir dankbar zu. {B} murmelt etwas von „Zugezogenen“ und stapft davon.","folgen":{"flag":["zaun_besucht","zaun_partei"],"sym":{"C":4,"B":-5}}}]},"zwischen":{"ort":"dorf","text":"Der Tag ist halb um. Die Leute haben gesehen, wo du warst.","optionen":[{"text":"Noch zum Zaunstreit","wenn":{"nicht_flag":"zaun_besucht"},"weiter":"zaun"},{"text":"Noch aufs Feld zu {A}","wenn":{"nicht_flag":"feld_besucht"},"weiter":"feld"},{"text":"Zum Feuer vor dem Langhaus","weiter":"abend"}]},"abend":{"ort":"feuer","text":"Am Abend brennt vor dem Langhaus ein Feuer. {V} reicht dir einen Becher warmen Apfelmost. „Die Leute reden über dich. Gut, meistens.“ Er zieht einen gefalteten Brief mit rotem Siegel aus der Jacke. „König Ottokar schreibt jedes Frühjahr. Steuern, Wege, Grenzen. Antworten müsste ein Dorfmeister – ich lege die Briefe in eine Kiste.“","optionen":[{"text":"„Warum stellst du dich nicht selbst zur Wahl?“","weiter":"ende","ergebnis":"„Vielleicht tue ich das. Irgendwer muss.“ Er starrt ins Feuer. „Aber ein Dorf verdient jemanden, der es will – nicht jemanden, der übrig bleibt.“","folgen":{"sym":{"V":2}}},{"text":"„Was müsste jemand tun, damit man ihm zuhört?“","weiter":"ende","ergebnis":"„Da sein, wenn es brennt. Und auch, wenn es nur nieselt.“ Er lächelt schief. „Hilf den Leuten bei ihren Bitten, nimm die Aufträge am Brett an, zieh los, wenn es draußen etwas zu klären gibt. Das spricht sich herum.“","folgen":{"flag":["rat"]}}]},"ende":{"ort":"feuer","ende":true,"text":"Als du später nach Hause gehst, nickt dir {A} aus dem Fenster zu. Kein großer Moment – aber ein Anfang. Im Dorf wird man sich an diesen Tag erinnern.","folgen":{"ansehen":12,"kapitel":2,"sym":{"V":2},"journal":["chronik_1","Ein Platz am Feuer","Seit Meister Gundrams Tod führt der Vorsteher das Dorf nur notgedrungen. Wer als Dorfmeister gewählt werden will, braucht Ansehen – durch Hilfe, Aufträge und Taten."],"chronik":["chronik_1","{held} half bei der Ernte und am Zaun – der erste Schritt zum Dazugehören."]}}}}},{"id":"chronik_2","titel":"Trübes Wasser","kurz":"Das Brunnenwasser ist trüb, Kinder haben Bauchweh – und am Brunnen sucht man schon einen Schuldigen.","kapitel":2,"rollen":{"V":"Vorsteher","A":"Wer beschuldigt wird","B":"Wer anklagt","C":"Wer mit zur Quelle geht"},"def":{"start":"brunnen","szenen":{"brunnen":{"ort":"dorf","text":"Am Brunnen steht eine Traube Menschen. Das Wasser im Eimer ist braun und riecht faulig, drei Kinder liegen mit Bauchkrämpfen im Bett. {B} schreit über alle hinweg: „Das ist {A}! Seit {A} oben am Bach arbeitet, ist das Wasser schlecht!“ {A} wird blass. {V} hebt die Hände, aber niemand hört auf ihn. Sein Blick sucht dich.","optionen":[{"text":"Die Menge beruhigen","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":12},"erfolg":{"text":"Du stellst dich auf den Brunnenrand und sprichst leise, bis die anderen leiser werden, um dich zu verstehen. „Erst nachsehen, dann urteilen.“ Die Fäuste sinken.","folgen":{"flag":["menge_ruhig"],"sym":{"A":3,"V":2}},"weiter":"aufbruch"},"misserfolg":{"text":"Deine Worte gehen im Geschrei unter. Ein paar Leute ziehen zu {A}s Haus und werfen mit Dreck. {A} sieht dich an, als hättest du es verhindern können.","folgen":{"flag":["tumult"],"sym":{"A":-1}},"weiter":"aufbruch"}},{"text":"„Ich gehe zur Quelle und finde heraus, was los ist.“","weiter":"aufbruch","ergebnis":"{V} atmet auf. „Nimm {C} mit. {C} kennt den Weg hinauf besser als jeder andere.“"},{"text":"„{B} hat recht – {A} soll dafür geradestehen!“","weiter":"beschuldigt"}]},"beschuldigt":{"ort":"dorf","text":"Jubel von {B}s Seite. {A} wird gezwungen, die Arbeit am Bach einzustellen, und schließt sich zu Hause ein. {V} schüttelt den Kopf. „Wir sehen trotzdem nach. Wenn {A} es war, finden wir es. Wenn nicht …“ Er spricht den Satz nicht zu Ende.","optionen":[{"text":"Zur Quelle aufbrechen","weiter":"aufbruch","folgen":{"flag":["ungerecht"],"sym":{"A":-6,"B":3},"merkt":{"A":"{held} hat mich vor allen beschuldigt, das Wasser vergiftet zu haben."}}}]},"aufbruch":{"ort":"wald","text":"{C} geht voraus, den Bach entlang, durch nassen Farn und über moosige Steine. Je höher ihr kommt, desto trüber wird das Wasser.","reise":{"minuten":1,"weiter":"quelle","text":"Der Weg zur Quelle führt bergauf durch dichten Wald."}},"quelle":{"ort":"wald","text":"Die Quelle liegt in einer Mulde unter einem Hang. Das alte hölzerne Rinnwerk, das das Wasser zum Dorf leitet, ist zerbrochen. Schlamm und Geröll sind vom Hang gerutscht, und in der Rinne hat sich etwas verfangen.","optionen":[{"text":"Den Hang und die Spuren untersuchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":11},"erfolg":{"text":"Die Erde ist frisch abgerutscht – nach den Regentagen. Keine Fußspuren, keine Gerberlohe. Nur der Berg, der sich bewegt hat.","folgen":{"flag":["ursache"]},"weiter":"quelle2"},"misserfolg":{"text":"Überall Schlamm. Was hier passiert ist, kannst du nicht sicher sagen.","weiter":"quelle2"}},{"text":"An die alte Steinrinne denken, von der die Alten erzählen","tag":"[Altes Wissen]","probe":{"id":"altes_wissen","dc":12},"erfolg":{"text":"Unter dem Moos findest du sie: Eine Rinne aus behauenen Steinen, viel älter als das Holz. Gundrams Großvater muss sie gebaut haben. Sie ist nur zugeschwemmt.","folgen":{"flag":["alte_rinne","ursache"]},"weiter":"quelle2"},"misserfolg":{"text":"Du erinnerst dich vage an Geschichten, aber nicht, wo genau sie lag.","weiter":"quelle2"}},{"text":"In der Rinne nachsehen, was sich dort verfangen hat","weiter":"quelle2","ergebnis":"Ein toter Fuchs, aufgedunsen, mitten im Wasserlauf. {C} würgt. Kein Wunder, dass das Wasser stinkt.","folgen":{"flag":["fuchs"]}}]},"quelle2":{"ort":"wald","text":"{C} krempelt die Ärmel hoch. „Wenn wir das heute nicht richten, trinkt das Dorf noch eine Woche Schlamm.“","optionen":[{"text":"Die Rinne flicken","weiter":"flicken"},{"text":"Die alte Steinrinne freilegen","wenn":{"flag":"alte_rinne"},"weiter":"heim","ergebnis":"Mit vereinten Kräften schaufelt ihr Stein um Stein frei. Die alte Rinne trägt das Wasser sauber und sicher – sie wird die nächste Regenzeit überstehen.","folgen":{"flag":["stein_frei","repariert"],"sym":{"C":4}}}]},"flicken":{"ort":"wald","text":"Bretter, Nägel und eine Handvoll Werkzeug – mehr habt ihr nicht. Der Hammer muss sitzen.","minispiel":{"art":"hammer","schwer":2,"titel":"Die Rinne flicken","text":"Schlag die Nägel sauber ein, damit das Wasser wieder läuft.","erfolg":{"text":"Die Rinne hält. Erst rinnt das Wasser braun, dann grau, dann klar. {C} jubelt.","folgen":{"flag":["repariert"],"sym":{"C":4},"merkt":{"C":"{held} hat mit mir an der Quelle die Wasserrinne geflickt."}},"weiter":"heim"},"misserfolg":{"text":"Ein Brett splittert, ihr müsst improvisieren. Die Rinne läuft – aber es wird nicht ewig halten.","folgen":{"flag":["halb"],"sym":{"C":2}},"weiter":"heim"}},"optionen":[]},"heim":{"ort":"dorf","text":"Zurück im Dorf wartet die Menge noch immer am Brunnen. {B} verschränkt die Arme, {A} steht abseits. Alle Blicke liegen auf dir.","optionen":[{"text":"Ruhig erklären, was du gefunden hast","wenn":{"flag":"ursache"},"weiter":"ende_gut","ergebnis":"Du erzählst vom abgerutschten Hang und der zerbrochenen Rinne. Kein Gift, keine Lohe – nur der Berg. Nach und nach nicken die Leute.","folgen":{"flag":["wahrheit"],"sym":{"A":5,"B":1},"merkt":{"A":"{held} hat vor allen bewiesen, dass ich nicht schuld war."}}},{"text":"Den toten Fuchs zeigen","wenn":{"flag":"fuchs"},"weiter":"ende_gut","ergebnis":"Du legst den Kadaver in einem Sack vor den Brunnen. Ein Raunen geht durch die Menge. {B} wird kleinlaut.","folgen":{"flag":["wahrheit"],"sym":{"A":4}}},{"text":"Alle aufrufen, die Quelle gemeinsam zu sichern","tag":"[Überreden]","probe":{"id":"ueberreden","dc":12},"erfolg":{"text":"„Jeder bringt morgen einen Stein und eine Schaufel mit!“ Und tatsächlich: Am nächsten Morgen zieht das halbe Dorf den Bach hinauf. Es wird ein Fest daraus.","folgen":{"flag":["gemeinschaft"],"dorf":{"stimmung":3}},"weiter":"ende_gut"},"misserfolg":{"text":"Ein paar Leute murmeln Zustimmung, die meisten gehen nach Hause. Immerhin: Das Wasser ist wieder klar.","weiter":"ende_hart"}},{"text":"{A} vor allen um Verzeihung bitten","wenn":{"flag":"ungerecht"},"weiter":"ende_hart","ergebnis":"Es fällt dir schwer, und alle hören zu. {A} nickt nur knapp. Vergessen ist es nicht – aber es ist ein Anfang.","folgen":{"sym":{"A":4}}},{"text":"{V} die Schuld geben – die Rinne hätte längst jemand prüfen müssen","weiter":"ende_hart","ergebnis":"Einige nicken. {V} steht stumm da und sagt nichts. Später siehst du ihn allein am Brunnen sitzen.","folgen":{"flag":["hart"],"sym":{"V":-6},"merkt":{"V":"{held} hat mich vor allen für das schlechte Wasser verantwortlich gemacht."}}}]},"ende_gut":{"ort":"dorf","ende":true,"text":"Am Abend schöpft {V} einen Becher klares Wasser und reicht ihn dir. „Du hast heute etwas getan, das ich nicht geschafft habe: Du hast die Leute zusammengehalten.“ Leiser fügt er hinzu: „Man fängt an, deinen Namen zu nennen, wenn von der Versammlung die Rede ist.“","folgen":{"ansehen":20,"kapitel":3,"dorf":{"stimmung":2,"nahrung":3},"sym":{"V":3},"journal":["chronik_2","Trübes Wasser","Die Quelle war verschüttet, nicht vergiftet. Man spricht davon, dass ich bei der nächsten Versammlung als Dorfmeister aufgestellt werden könnte – wenn mein Ansehen weiter wächst."],"chronik":["chronik_2","{held} brachte das Wasser zurück und hielt das Dorf zusammen, als es nach einem Schuldigen suchte."]}},"ende_hart":{"ort":"dorf","ende":true,"text":"Das Wasser ist wieder klar, aber der Tag hinterlässt einen schalen Geschmack. Trotzdem: Die Leute haben gesehen, dass du hinaufgegangen bist, als andere nur geschrien haben.","folgen":{"ansehen":12,"kapitel":3,"dorf":{"nahrung":2},"journal":["chronik_2","Trübes Wasser","Das Wasser fließt wieder. Wer bei der Versammlung als Dorfmeister antreten will, braucht noch mehr Ansehen."],"chronik":["chronik_2","{held} brachte das Wasser zurück – nicht ohne Streit."]}}}}},{"id":"chronik_3","titel":"Die Versammlung","kurz":"Der Rat ruft die Bürgerversammlung zusammen. Man nennt deinen Namen – und {V} will das Amt behalten.","kapitel":3,"rollen":{"V":"Vorsteher (Gegenkandidat)","A":"Wer zu dir hält","B":"Wer zweifelt","C":"Wer ein Versprechen will"},"def":{"start":"aufruf","szenen":{"aufruf":{"ort":"dorf","text":"Am Brett hängt ein frischer Aushang: Bürgerversammlung im Langhaus, morgen bei Sonnenuntergang. Darunter, in {V}s krakeliger Schrift, zwei Namen. Einer davon ist deiner. {V} tritt neben dich. „Ich trete auch an. Ich habe das Dorf durch den Winter gebracht – das soll etwas zählen.“","optionen":[{"text":"„Möge der Bessere gewinnen.“","weiter":"runde","folgen":{"sym":{"V":2}}},{"text":"„Du hast es gut gemacht. Aber das Dorf braucht mehr als Durchhalten.“","weiter":"runde"},{"text":"„Tritt zurück. Du bist müde, das sieht jeder.“","weiter":"runde","folgen":{"sym":{"V":-5},"merkt":{"V":"{held} hat mir vor der Versammlung geraten, aufzugeben."}}}]},"runde":{"ort":"dorf","text":"Bis zur Versammlung bleibt dir ein Tag. Wen willst du noch aufsuchen?","optionen":[{"text":"{A} besuchen","wenn":{"nicht_flag":"besuch_a"},"weiter":"besuch_a"},{"text":"{B} besuchen – {B} zweifelt an dir","wenn":{"nicht_flag":"besuch_b"},"weiter":"besuch_b"},{"text":"{C} besuchen – {C} will etwas von dir","wenn":{"nicht_flag":"besuch_c"},"weiter":"besuch_c"},{"text":"Zur Versammlung ins Langhaus","weiter":"versammlung"}]},"besuch_a":{"ort":"dorf","text":"{A} empfängt dich mit einem Grinsen. „Ich weiß schon, was ich ins Töpfchen werfe. Soll ich morgen etwas für dich sagen, bevor du sprichst?“","optionen":[{"text":"„Das wäre mir eine Ehre.“","weiter":"runde","folgen":{"flag":["besuch_a","stimme_a"],"sym":{"A":2}}},{"text":"„Lieber nicht – die Leute sollen selbst entscheiden.“","weiter":"runde","ergebnis":"{A} nickt anerkennend. „So einer bist du also.“","folgen":{"flag":["besuch_a"],"sym":{"A":3}}}]},"besuch_b":{"ort":"dorf","text":"{B} lässt dich nur bis zur Tür. „Was weißt du schon vom Führen? Unter Gundram haben wir drei magere Jahre gehabt, und er war ein kluger Mann.“","optionen":[{"text":"Herausfinden, was {B} wirklich fürchtet","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":12},"erfolg":{"text":"Es geht nicht um dich. {B} hat damals den Hof der Eltern verloren, weil niemand half. Du versprichst nichts Großes – nur, dass bei dir niemand allein gelassen wird. {B} schweigt lange. „Ich denk drüber nach.“","folgen":{"flag":["besuch_b","stimme_b"],"sym":{"B":4},"merkt":{"B":"{held} hat verstanden, warum ich Angst vor einem neuen Dorfmeister habe."}},"weiter":"runde"},"misserfolg":{"text":"{B} schließt die Tür. Vielleicht war heute nicht der richtige Tag.","folgen":{"flag":["besuch_b"]},"weiter":"runde"}},{"text":"Mit Taten überzeugen: an Brunnen und Ernte erinnern","tag":"[Überreden]","probe":{"id":"ueberreden","dc":13},"erfolg":{"text":"„Das stimmt wohl“, brummt {B}. „Du warst da, als andere nur geredet haben.“","folgen":{"flag":["besuch_b","stimme_b"],"sym":{"B":2}},"weiter":"runde"},"misserfolg":{"text":"„Ein paar gute Tage machen noch keinen Dorfmeister.“ Die Tür bleibt halb geschlossen.","folgen":{"flag":["besuch_b"]},"weiter":"runde"}}]},"besuch_c":{"ort":"dorf","text":"{C} kommt gleich zur Sache. „Das Unterdorf hat keinen eigenen Brunnen. Versprich mir, dass du einen bauen lässt, wenn du gewählt wirst – dann hast du meine Stimme und die meiner Nachbarn.“","optionen":[{"text":"„Versprochen.“","weiter":"runde","folgen":{"flag":["besuch_c","stimme_c","versprechen_brunnen"],"sym":{"C":3},"merkt":{"C":"{held} hat mir vor der Wahl einen Brunnen fürs Unterdorf versprochen."}}},{"text":"Etwas Kleineres aushandeln: zuerst eine neue Pumpe","tag":"[Feilschen]","probe":{"id":"feilschen","dc":11},"erfolg":{"text":"{C} überlegt, dann schlägt er ein. „Eine Pumpe. Aber eine ordentliche.“","folgen":{"flag":["besuch_c","stimme_c"],"sym":{"C":2}},"weiter":"runde"},"misserfolg":{"text":"„Also willst du gar nichts versprechen.“ {C} wendet sich ab.","folgen":{"flag":["besuch_c"],"sym":{"C":-1}},"weiter":"runde"}},{"text":"„Ich verspreche nichts, was ich nicht sicher halten kann.“","weiter":"runde","ergebnis":"{C} mustert dich. „Ehrlich. Selten genug.“ Ob das für eine Stimme reicht, verrät {C} nicht.","folgen":{"flag":["besuch_c"],"sym":{"C":2}}}]},"versammlung":{"ort":"feuer","text":"Das Langhaus ist voll bis unter die Balken, Fackeln qualmen, Kinder sitzen auf den Schultern der Eltern. {V} spricht zuerst – ruhig, ehrlich, von einem harten Winter, den alle überlebt haben. Es gibt Beifall. Dann wird es still. Alle sehen dich an.","optionen":[{"text":"Ehrlich sagen, was du im Dorf gesehen hast – und was fehlt","weiter":"abstimmung","ergebnis":"Du sprichst vom Wasser, vom Zaun, von den Briefen des Königs in {V}s Kiste. Keine großen Worte. Hier und da nickt jemand.","folgen":{"flag":["rede_ehrlich"]}},{"text":"Ein Bild von der Zukunft malen: Markt, Mauern, Ansehen beim König","tag":"[Überreden]","probe":{"id":"ueberreden","dc":13},"erfolg":{"text":"Du redest, und die Leute vergessen das Qualmen der Fackeln. Am Ende ruft jemand von hinten deinen Namen, und andere stimmen ein.","folgen":{"flag":["rede_gut"]},"weiter":"abstimmung"},"misserfolg":{"text":"Du verhaspelst dich, die großen Worte klingen hohl. Ein paar Leute grinsen.","folgen":{"flag":["rede_holprig"]},"weiter":"abstimmung"}},{"text":"{V} danken und vorschlagen, ihn als Ratgeber zu behalten","weiter":"abstimmung","ergebnis":"{V} sieht überrascht auf. Ein warmes Murmeln geht durch den Saal – so redet man hier gern miteinander.","folgen":{"flag":["rede_demut"],"sym":{"V":6},"merkt":{"V":"{held} hat mich vor allen gewürdigt und mir einen Platz im Rat angeboten."}}},{"text":"{V}s Fehler aufzählen","weiter":"abstimmung","ergebnis":"Du zählst auf, was im Winter schiefging. Es ist alles wahr – und trotzdem verziehen manche das Gesicht. Man tritt nicht nach.","folgen":{"flag":["rede_angriff"],"sym":{"V":-8},"merkt":{"V":"{held} hat vor der Versammlung über mich hergezogen."}}}]},"abstimmung":{"ort":"feuer","ende":true,"text":"Jeder Bewohner legt eine Bohne in einen der beiden Krüge – weiß für dich, schwarz für {V}. Es ist so still, dass man das Klicken der Bohnen hört. Dann kippt der Älteste die Krüge auf den Tisch und beginnt zu zählen.","folgen":{"ansehen":5,"wahl":true,"journal":["chronik_3","Die Versammlung","Bei der Bürgerversammlung im Langhaus stand ich gegen den Vorsteher zur Wahl."]}}}}}]$q$::jsonb) e
on conflict (id) do update set titel = excluded.titel, beschreibung = excluded.beschreibung, kurz = excluded.kurz, art = excluded.art, schwierigkeit = excluded.schwierigkeit, rollen = excluded.rollen, def = excluded.def;

insert into public.dorf_vorlagen (id, art, titel, text, optionen, rollen, auto, gewicht)
select e->>'id', e->>'art', e->>'titel', e->>'text', e->'optionen', array(select jsonb_array_elements_text(e->'rollen')), (e->>'auto')::int, (e->>'gewicht')::numeric from jsonb_array_elements($q$[{"id":"brotdieb","art":"rechtsfall","titel":"Brot aus der Vorratskammer","text":"{O} hat {T} beim Diebstahl von zwei Laiben Brot erwischt. {T} sagt, die Kinder hätten seit zwei Tagen kaum gegessen. {O} will eine Strafe sehen.","optionen":[{"text":"Verzeihen – {T} arbeitet es bei {O} ab","ergebnis":"{T} schuftet eine Woche bei {O}. Am Ende teilen die beiden sogar ein Abendbrot.","folgen":{"sym":{"T":6,"O":-1},"stim":1}},{"text":"Eine Buße in Waren zahlen lassen","ergebnis":"{T} zahlt mit dem wenigen, was da ist. {O} ist zufrieden, {T} verbittert.","folgen":{"sym":{"T":-4,"O":3},"res":{"waren":2}}},{"text":"Einen Tag an den Pranger","ergebnis":"Der Pranger lockt Zuschauer und Spott. Gestohlen wird so schnell nicht mehr – aber die Stimmung ist gedrückt.","folgen":{"sym":{"T":-10,"O":2},"stim":-2}},{"text":"Aus der Gemeinschaftskasse Brot für die Familie geben","ergebnis":"Niemand muss im Dorf hungern, sagst du. {O} murrt, die anderen nicken.","folgen":{"sym":{"T":8,"O":-2},"res":{"nahrung":-4},"stim":2,"ansehen":1}}],"rollen":["T","O"],"auto":1,"gewicht":1},{"id":"grenzstein","art":"rechtsfall","titel":"Der wandernde Grenzstein","text":"Der Grenzstein zwischen den Äckern von {T} und {O} steht über Nacht drei Schritte weiter in {O}s Feld. {T} schwört, nichts damit zu tun zu haben.","optionen":[{"text":"Den Stein zurücksetzen und {T} verwarnen","ergebnis":"Der Stein kommt zurück an seinen Platz. {T} schweigt verbissen.","folgen":{"sym":{"T":-3,"O":3}}},{"text":"Die Alten befragen, wo die Grenze wirklich lag","ergebnis":"Die Alten streiten eine Stunde – und geben {O} recht. Die Sache ist sauber entschieden.","folgen":{"sym":{"T":-2,"O":4},"stim":1}},{"text":"Einen Streifen Gemeindeland als Ausgleich teilen","ergebnis":"Beide bekommen ein Stück mehr, keiner hat ganz verloren. Ungewöhnlich, aber es wirkt.","folgen":{"sym":{"T":3,"O":2},"res":{"nahrung":-2},"stim":1}}],"rollen":["T","O"],"auto":0,"gewicht":1},{"id":"schlaegerei","art":"rechtsfall","titel":"Schlägerei in der Schenke","text":"Gestern Abend sind {T} und {O} in der Schenke aneinandergeraten. Ein Tisch ist zerbrochen, {O} hat ein blaues Auge. Jeder sagt, der andere habe angefangen.","optionen":[{"text":"Beide zahlen den Tisch je zur Hälfte","ergebnis":"Beide zahlen zähneknirschend. Der Wirt ist zufrieden.","folgen":{"sym":{"T":-1,"O":-1},"res":{"waren":1}}},{"text":"{T} muss sich öffentlich entschuldigen","ergebnis":"{T} entschuldigt sich vor allen. {O} grinst schief.","folgen":{"sym":{"T":-4,"O":3}}},{"text":"Beide eine Woche gemeinsam Holz hacken lassen","ergebnis":"Nach drei Tagen reden sie wieder miteinander, nach fünf lachen sie. Und der Holzstapel wächst.","folgen":{"sym":{"T":2,"O":2},"res":{"holz":6},"stim":1}}],"rollen":["T","O"],"auto":0,"gewicht":1},{"id":"schulden","art":"rechtsfall","titel":"Geliehenes Silber","text":"{O} hat {T} im Frühjahr Silber für Saatgut geliehen. Die Ernte war mager, und {T} kann nicht zurückzahlen. {O} verlangt, dass {T} die Kuh hergibt.","optionen":[{"text":"{T} muss die Kuh abgeben","ergebnis":"{O} bekommt die Kuh. {T}s Familie wird den Winter ohne Milch verbringen.","folgen":{"sym":{"T":-8,"O":4},"stim":-1}},{"text":"Aufschub bis zur nächsten Ernte gewähren","ergebnis":"{O} murrt, aber willigt ein – mit deinem Wort als Pfand.","folgen":{"sym":{"T":5,"O":-2}}},{"text":"Das Dorf übernimmt einen Teil der Schuld","ergebnis":"Aus den Vorräten wird ein Teil beglichen. {O} ist zufrieden, {T} unendlich dankbar.","folgen":{"sym":{"T":7,"O":2},"res":{"waren":-3},"ansehen":1}}],"rollen":["T","O"],"auto":1,"gewicht":1},{"id":"wilderei","art":"rechtsfall","titel":"Wilderei im Königsforst","text":"Ein Förster des Königs hat {T} mit einem erlegten Hirsch im Königsforst erwischt. Er verlangt, dass das Dorf den Wilderer bestraft – sonst meldet er es dem König.","optionen":[{"text":"{T} hart bestrafen, wie das Gesetz es will","ergebnis":"{T} muss eine schwere Buße zahlen. Der Förster nickt zufrieden.","folgen":{"sym":{"T":-8},"gunst":5,"stim":-1}},{"text":"Den Förster mit Waren besänftigen","ergebnis":"Ein paar Ballen Tuch, und der Förster hat nichts gesehen. Der König erfährt nichts – vorerst.","folgen":{"res":{"waren":-4},"sym":{"T":4}}},{"text":"{T} in Schutz nehmen: Das Dorf hungert, der König hat genug Hirsche","ergebnis":"Die Leute jubeln dir zu. Der Förster reitet wütend davon.","folgen":{"sym":{"T":6},"gunst":-8,"stim":3,"ansehen":1}}],"rollen":["T"],"auto":0,"gewicht":1},{"id":"geruecht","art":"rechtsfall","titel":"Böse Zungen","text":"{T} erzählt überall, {O} habe die eigene Ziege verhext, weil die Milch sauer wurde. Kinder werfen schon mit Steinen nach {O}s Tür.","optionen":[{"text":"{T} öffentlich zur Rede stellen","ergebnis":"{T} muss vor allen zugeben, dass es nur Gerede war. Die Steine hören auf.","folgen":{"sym":{"T":-4,"O":5}}},{"text":"Die Kinder zurechtweisen und die Sache ruhen lassen","ergebnis":"Die Steine hören auf, das Gerede nicht ganz.","folgen":{"sym":{"O":2}}},{"text":"{T} aus dem Dorf weisen","ergebnis":"{T} packt die Sachen. Niemand wird hier mehr wegen Hexerei verdächtigt – aber manche flüstern jetzt über dich.","folgen":{"verbannen":"T","sym":{"O":6},"stim":-3}}],"rollen":["T","O"],"auto":1,"gewicht":1},{"id":"fundsache","art":"rechtsfall","titel":"Der Beutel im Bach","text":"{T} hat im Bach einen Lederbeutel mit Münzen gefunden. {O} behauptet, es sei der eigene – kann es aber nicht beweisen.","optionen":[{"text":"{O} soll den Inhalt beschreiben","ergebnis":"{O} beschreibt die Münzen genau, bis auf die Kerbe in einer davon. Der Beutel geht zurück.","folgen":{"sym":{"O":4,"T":1}}},{"text":"Der Finder darf ihn behalten","ergebnis":"{T} strahlt. {O} geht wortlos.","folgen":{"sym":{"T":4,"O":-4}}},{"text":"Den Inhalt für die Dorfkasse einziehen","ergebnis":"Beide gehen leer aus, aber das Dorf hat etwas davon.","folgen":{"sym":{"T":-2,"O":-2},"res":{"waren":3}}}],"rollen":["T","O"],"auto":0,"gewicht":1},{"id":"schweine","art":"rechtsfall","titel":"Schweine im Gemüsegarten","text":"{T}s Schweine haben über Nacht {O}s Gemüsegarten verwüstet. Kohl, Rüben, alles zertrampelt.","optionen":[{"text":"{T} ersetzt den Schaden mit Nahrung","ergebnis":"{T} bringt zwei Säcke Rüben. {O} ist besänftigt.","folgen":{"sym":{"T":-2,"O":3}}},{"text":"Beide bauen gemeinsam einen festen Zaun","ergebnis":"Ein Zaun, der hält – und ein Nachmittag, an dem die beiden wieder miteinander reden.","folgen":{"sym":{"T":2,"O":2},"res":{"holz":-3}}},{"text":"Ein Schwein wird geschlachtet und geteilt","ergebnis":"Es gibt ein kleines Fest. {T} ist nicht begeistert, alle anderen schon.","folgen":{"sym":{"T":-3,"O":2},"res":{"nahrung":5},"stim":2}}],"rollen":["T","O"],"auto":0,"gewicht":1},{"id":"fieber","art":"krise","titel":"Fieber im Unterdorf","text":"In drei Häusern liegen Leute mit hohem Fieber. {H} meint, es könnte sich ausbreiten.","optionen":[{"text":"Die Häuser absperren, bis es vorüber ist","ergebnis":"Die Kranken bleiben unter sich. Das Fieber breitet sich nicht aus, aber die Arbeit bleibt liegen.","folgen":{"res":{"nahrung":-3,"waren":-2},"stim":-1}},{"text":"{H} soll mit Kräutern von Haus zu Haus gehen","ergebnis":"{H} wacht drei Nächte durch. Das Fieber sinkt, und alle wissen, wem sie es verdanken.","folgen":{"sym":{"H":5},"res":{"waren":-2},"stim":2}},{"text":"Abwarten – Fieber kommt und geht","ergebnis":"Nach einer Woche liegt das halbe Dorf flach. Es geht gut aus, aber die Leute sind verstimmt.","folgen":{"stim":-4,"res":{"nahrung":-2}}}],"rollen":["H"],"auto":1,"gewicht":1},{"id":"scheunenbrand","art":"krise","titel":"Feuer in der Scheune","text":"Mitten in der Nacht brennt eine Scheune! Die Flammen greifen nach dem Nachbardach. {H} läuft schon mit Eimern.","optionen":[{"text":"Alle zur Eimerkette – das Dach retten","ergebnis":"Eine lange Kette bis zum Bach. Die Scheune ist verloren, das Nachbarhaus gerettet.","folgen":{"res":{"holz":-5},"stim":2,"sym":{"H":3}}},{"text":"Erst das Korn aus der Scheune holen","ergebnis":"Ihr rettet die Hälfte des Korns. Das Nachbardach fängt Feuer und brennt ab.","folgen":{"res":{"nahrung":3,"holz":-9},"stim":-2}},{"text":"Das Vieh befreien und die Flammen eindämmen","ergebnis":"Kein Tier verbrennt. Das Feuer frisst die Scheune, aber nicht mehr.","folgen":{"res":{"holz":-6},"stim":1}}],"rollen":["H"],"auto":0,"gewicht":1},{"id":"woelfe","art":"krise","titel":"Wölfe an den Weiden","text":"Zwei Schafe sind gerissen, und im Morgennebel hat {H} ein Rudel am Waldrand gesehen.","optionen":[{"text":"Eine Jagd ausrufen","ergebnis":"Die Jäger ziehen los und kommen mit zwei Fellen zurück. Das Rudel weicht in die Berge.","folgen":{"sym":{"H":3},"res":{"waren":2},"stim":1}},{"text":"Feste Pferche für die Nacht bauen","ergebnis":"Die Pferche kosten Holz, aber kein Schaf geht mehr verloren.","folgen":{"res":{"holz":-5}}},{"text":"Feuer an den Weiden brennen lassen","ergebnis":"Die Feuer halten die Wölfe fern – und verbrauchen jede Nacht Holz.","folgen":{"res":{"holz":-3},"stim":1}}],"rollen":["H"],"auto":1,"gewicht":1},{"id":"duerre","art":"krise","titel":"Der Brunnen sinkt","text":"Seit Wochen kein Regen. Der Brunnen gibt nur noch trübes Wasser, und die Felder werden gelb.","optionen":[{"text":"Den Brunnen tiefer graben","ergebnis":"Drei Tage Arbeit, und dann sprudelt es wieder. Es hat Steine und Schweiß gekostet.","folgen":{"res":{"stein":-5},"stim":1}},{"text":"Wasser rationieren","ergebnis":"Jeder bekommt seinen Anteil. Es reicht – knapp, und mit langen Gesichtern.","folgen":{"stim":-2}},{"text":"Wasser vom Bach in Fässern heranschaffen","ergebnis":"Ein mühsamer Weg, aber die Felder werden gerettet.","folgen":{"res":{"holz":-3,"nahrung":2}}}],"rollen":[],"auto":1,"gewicht":1},{"id":"sturm","art":"krise","titel":"Nach dem Sturm","text":"Ein Herbststurm hat Dächer abgedeckt und Bäume entwurzelt. {H} fragt, womit man anfangen soll.","optionen":[{"text":"Zuerst die Häuser der Alten und Kranken","ergebnis":"Die Schwächsten haben als Erste wieder ein Dach. Das spricht sich herum.","folgen":{"res":{"holz":-4},"stim":3}},{"text":"Zuerst die Vorratsscheunen","ergebnis":"Das Korn bleibt trocken. Ein paar Leute schlafen zwei Nächte im Langhaus.","folgen":{"res":{"holz":-4,"nahrung":2}}},{"text":"Das Sturmholz sammeln und verkaufen","ergebnis":"Aus dem Unglück wird ein kleines Geschäft. Die Dächer warten etwas länger.","folgen":{"res":{"holz":6,"waren":2},"stim":-2}}],"rollen":["H"],"auto":0,"gewicht":1},{"id":"fluechtlinge","art":"krise","titel":"Fremde am Dorfrand","text":"Eine Familie mit einem Karren steht am Dorfrand – Flüchtlinge aus einem Dorf jenseits der Berge, das abgebrannt ist. Sie bitten um Obdach.","optionen":[{"text":"Sie aufnehmen","ergebnis":"Die Familie bleibt. Sie bringen fleißige Hände mit – und hungrige Münder.","folgen":{"zuzug":1,"res":{"nahrung":-3},"stim":1,"ansehen":1}},{"text":"Ihnen Vorräte geben und weiterschicken","ergebnis":"Mit gefüllten Säcken ziehen sie weiter. Sie danken dir trotzdem.","folgen":{"res":{"nahrung":-3}}},{"text":"Sie abweisen","ergebnis":"Der Karren rollt davon. Ein paar Kinder winken ihm nach.","folgen":{"stim":-2}}],"rollen":[],"auto":1,"gewicht":1},{"id":"steuer","art":"koenig","titel":"Der Steuereintreiber","text":"Ein Steuereintreiber König Ottokars steht mit zwei Bewaffneten am Brunnen. Er verlangt den Herbstzehnt: Holz und Waren.","optionen":[{"text":"Den vollen Zehnt zahlen","ergebnis":"Der Eintreiber notiert alles sorgfältig. „Der König wird es erfahren.“","folgen":{"res":{"holz":-8,"waren":-4},"gunst":8}},{"text":"Um Aufschub bitten – die Ernte war mager","ergebnis":"Der Eintreiber gewährt einen Monat. Freundlich ist er dabei nicht.","folgen":{"gunst":-2}},{"text":"Nur die Hälfte zahlen","ergebnis":"Der Eintreiber zieht die Brauen hoch, nimmt aber, was er kriegt.","folgen":{"res":{"holz":-4,"waren":-2},"gunst":1}},{"text":"Die Zahlung verweigern","ergebnis":"Der Eintreiber reitet davon. Im Dorf feiern sie dich – in der Burg wird man das anders sehen.","folgen":{"gunst":-12,"stim":3}}],"rollen":[],"auto":0,"gewicht":1},{"id":"truppen","art":"koenig","titel":"Männer für die Grenze","text":"Ein Bote des Königs bringt einen Befehl: Das Dorf soll zwei kräftige Leute für den Grenzwall stellen, für einen Sommer.","optionen":[{"text":"Zwei Freiwillige schicken","ergebnis":"Zwei junge Leute ziehen los, stolz und ein bisschen ängstlich. Der König merkt sich die Treue.","folgen":{"gunst":8,"stim":-2}},{"text":"Statt Leuten Vorräte schicken","ergebnis":"Ein Karren mit Proviant rollt zur Grenze. Der Bote ist halbwegs zufrieden.","folgen":{"res":{"nahrung":-6},"gunst":3}},{"text":"Den Befehl ablehnen – die Hände werden gebraucht","ergebnis":"Der Bote zieht mit grimmigem Gesicht ab.","folgen":{"gunst":-8,"stim":1}}],"rollen":[],"auto":0,"gewicht":1},{"id":"gesandter","art":"koenig","titel":"Ein Gesandter auf Durchreise","text":"Ein Gesandter des Königs reist mit Gefolge durch und will im Dorf übernachten.","optionen":[{"text":"Ein Fest zu seinen Ehren","ergebnis":"Musik, Braten, Tanz. Der Gesandte reist mit glänzenden Augen weiter – und lobt das Dorf in der Burg.","folgen":{"res":{"nahrung":-6},"gunst":6,"stim":2}},{"text":"Einfache, ehrliche Gastfreundschaft","ergebnis":"Brot, Suppe, ein warmes Bett. Der Gesandte bedankt sich höflich.","folgen":{"res":{"nahrung":-2},"gunst":2}},{"text":"Ihn an die Schenke verweisen","ergebnis":"Der Gesandte rümpft die Nase und bezahlt für sein Zimmer.","folgen":{"gunst":-3,"res":{"waren":1}}}],"rollen":[],"auto":1,"gewicht":1},{"id":"burgholz","art":"koenig","titel":"Holz für die Burg","text":"König Ottokar lässt seine Burg ausbauen. Ein Baumeister bittet um Bauholz aus euren Wäldern.","optionen":[{"text":"Reichlich Holz liefern","ergebnis":"Lange Stämme rollen zur Burg. Der Baumeister verspricht, den König daran zu erinnern.","folgen":{"res":{"holz":-10},"gunst":7}},{"text":"Eine kleine Lieferung","ergebnis":"Ein Wagen Holz – nicht viel, aber guter Wille.","folgen":{"res":{"holz":-4},"gunst":2}},{"text":"Ablehnen, das Dorf braucht sein Holz","ergebnis":"Der Baumeister zieht leer ab.","folgen":{"gunst":-5}}],"rollen":[],"auto":1,"gewicht":1},{"id":"antritt","art":"koenig","titel":"Ein Brief mit rotem Siegel","text":"Ein Reiter bringt einen Brief von König Ottokar: Er hat von deiner Wahl gehört und erwartet, dass du ihm als Dorfmeister die Treue schwörst – als seine rechte Hand in diesem Tal.","optionen":[{"text":"Dem König feierlich die Treue schwören","ergebnis":"Der Reiter nimmt deinen Schwur mit. „Der König vergisst seine Getreuen nicht.“","folgen":{"gunst":12}},{"text":"Höflich antworten, aber nichts versprechen","ergebnis":"Ein kluger Brief: freundlich, unverbindlich. Man wird in der Burg darüber nachdenken.","folgen":{"gunst":3}},{"text":"Kühl antworten: Das Dorf gehört seinen Bewohnern","ergebnis":"Der Reiter liest den Brief mit hochgezogenen Brauen. Im Dorf erzählt man es sich mit Stolz.","folgen":{"gunst":-8,"stim":2}}],"rollen":[],"auto":0,"gewicht":0},{"id":"bittsteller","art":"bittsteller","titel":"Ein Bittsteller am Tor","text":"{T}, {beruf}, steht mit einem Bündel am Dorfplatz und bittet darum, im Dorf wohnen zu dürfen. {wesen}","optionen":[{"text":"Aufnehmen","ergebnis":"{T} bedankt sich und sucht sich eine Ecke im Dorf.","folgen":{"zuzug":1}},{"text":"Abweisen","ergebnis":"{T} nickt stumm und zieht weiter.","folgen":{"stim":0}}],"rollen":["T"],"auto":0,"gewicht":0}]$q$::jsonb) e
on conflict (id) do update set art = excluded.art, titel = excluded.titel, text = excluded.text, optionen = excluded.optionen, rollen = excluded.rollen, auto = excluded.auto, gewicht = excluded.gewicht;
